{
"predictors": [
{
"name": "Customer Satisfaction",
"construction": "Measured through customer reviews and ratings on social media and e-commerce platforms over the past year.",
"rationale": "Firms with higher customer satisfaction may have a stronger brand or customer loyalty, which could lead to higher future profits.",
"higher_returns_for": "High values of the measure"
},
{
"name": "Product Development Cycle Time",
"construction": "Calculated as the time taken from initial product concept to market launch, averaged over the past 2 years.",
"rationale": "Faster product development could reflect a firm's efficiency or innovative capability, potentially leading to competitive advantage and higher future returns.",
"higher_returns_for": "Low values of the measure"
},
{
"name": "Employee Morale",
"construction": "Measured through employee surveys or third-party evaluations, averaged over the past year.",
"rationale": "Higher morale may increase productivity and reduce employee turnover, potentially improving firm performance.",
"higher_returns_for": "High values of the measure"
},
{
"name": "Corporate Social Responsibility (CSR) Score",
"construction": "Measured via third-party CSR ratings based on environmental, social, governance (ESG) factors.",
"rationale": "High-scoring CSR firms might attract more socially conscious consumers or investors, potentially leading to higher demand for their products or shares.",
"higher_returns_for": "High values of the measure"
},
{
"name": "Data Breach Incidents",
"construction": "Count the number of reported data breaches in the past 3 years.",
"rationale": "Firms with more data breaches may face reputational damage and regulatory fines, potentially harming future profits.",
"higher_returns_for": "Low values of the measure"
},
{
"name": "Patent Applications",
"construction": "Count the number of patent applications filed in the past 1 year.",
"rationale": "A larger number of patent applications may signal a firm's innovation and potential for future profit growth.",
"higher_returns_for": "High values of the measure"
},
{
"name": "Supply Chain Robustness",
"construction": "Measured by the number of unique suppliers and geographical diversity of supply sources.",
"rationale": "Firms with more robust supply chains might be better protected against supply disruptions, which could stabilize their profits.",
"higher_returns_for": "High values of the measure"
},
{
"name": "CEO-Worker Pay Ratio",
"construction": "Calculated as the CEO's total compensation divided by the median employee's pay.",
"rationale": "A lower ratio might reflect more equitable wealth distribution within the firm, potentially improving employee morale and productivity.",
"higher_returns_for": "Low values of the measure"
},
{
"name": "Number of Recalls",
"construction": "Count the number of product recalls over the past 3 years.",
"rationale": "Firms with more recalls may have lower product quality or safety, which could harm their reputation and future profits.",
"higher_returns_for": "Low values of the measure"
},
{
"name": "Percentage of Independent Directors",
"construction": "Calculated as the number of independent directors divided by the total number of board members.",
"rationale": "A higher percentage could lead to better corporate governance, potentially reducing firm risk and increasing investor confidence.",
"higher_returns_for": "High values of the measure"
}
]
}
